#include "api.cpp"
#include <cassert>
int main(int argc,char**argv){std::ifstream f(argv[1],std::ios::binary);std::vector<uint8_t>b((std::istreambuf_iterator<char>(f)),{});std::copy(b.begin(),b.end(),rr_input(b.size()));assert(rr_init(b.size()));b.clear();b.shrink_to_fit();while(machine->vblankCount<60){if(rr_run(50000)<0)throw std::runtime_error(errorText);}auto n=rr_state_save();if(!n){rrstate::Archive a;stateWrite(a);}assert(n);std::vector<uint8_t>saved(rr_state_data(),rr_state_data()+n);for(int i=0;i<100;i++)assert(rr_run(10000)>=0);auto expected=proof(machine);std::copy(saved.begin(),saved.end(),rr_state_input(saved.size()));assert(rr_state_load(saved.size()));for(int i=0;i<100;i++)assert(rr_run(10000)>=0);assert(proof(machine)==expected);std::cerr<<"State continuation passed: "<<n<<" bytes\n";
 for(int attempt=0;attempt<12;attempt++){assert(rr_capture_begin());auto f0=machine->vblankCount;while(machine->vblankCount==f0)assert(rr_run(10000)>=0);assert(rr_capture_end());if(rrcapture::trace.events.size()>10)break;}std::cerr<<rr_capture_info()<<"\n";auto live=frame(machine);rr_replay_begin();while(!rr_replay_seek(rrreplay::replay.steps.size())){}auto replay=rr3ds::display(rrreplay::replay.memory);if(live!=replay){int n=0;for(int i=0;i<live.size();i++)if(live[i]!=replay[i])n++;std::cerr<<"Replay difference "<<n<<" bytes\n";return 2;}assert(rrcapture::trace.overflow==0);assert(rrcapture::trace.shadow==rrcapture::trace.final);std::cout<<"State/capture/replay pass\n";std::ofstream out("/private/tmp/3ds-browser.state",std::ios::binary);n=rr_state_save();out.write((char*)rr_state_data(),n);}
